import { createPerson, getPersons } from "../components/apiutils";
import Nav from "../components/Nav";
import { useState, useEffect } from "react";

export default function UserMgmt() {
    const [users, setUsers] = useState([]);
    const [formData, setFormData] = useState({ name: "", email: "", mobile: "" });

    useEffect(() => {
        getPersons()
            .then((personList) => {
                const normalizedUsers = (personList || []).map((user) => ({
                    ...user,
                    phoneNumber: user.phoneNumber || user.mobile || ""
                }));
                setUsers(normalizedUsers);
            })
            .catch(() => {
                setUsers([]);
            });
    }, []);

    const handleChange = (event) => {
        const { name, value } = event.target;
        setFormData((prev) => ({ ...prev, [name]: value }));
    };

    const handleSubmit = async (event) => {
        event.preventDefault();

        const newUser = {
            name: formData.name,
            email: formData.email,
            phoneNumber: formData.mobile,
            mobile: formData.mobile
        };

        setUsers((prevUsers) => [...prevUsers, newUser]);

        try {
            await createPerson({
                name: formData.name,
                email: formData.email,
                mobile: formData.mobile
            });
        } catch (error) {
            console.error("Failed to save user", error);
        }

        setFormData({ name: "", email: "", mobile: "" });
    };

    return (
        <>
            <Nav>
                <div style={{ padding: "20px" }}>
                    <form onSubmit={handleSubmit} style={{ marginBottom: "20px" }}>
                        <div>
                            <label htmlFor="name">Name:</label>
                            <input id="name" name="name" value={formData.name} onChange={handleChange} required />
                        </div>
                        <div>
                            <label htmlFor="email">Email:</label>
                            <input id="email" name="email" type="email" value={formData.email} onChange={handleChange} required />
                        </div>
                        <div>
                            <label htmlFor="mobile">Mobile:</label>
                            <input id="mobile" name="mobile" value={formData.mobile} onChange={handleChange} required />
                        </div>
                        <button type="submit">Submit</button>
                    </form>

                    <table>
                        <thead>
                            <tr>
                                <th>Name</th>
                                <th>Email</th>
                                <th>Phone</th>
                            </tr>
                        </thead>
                        <tbody>
                            {users.map((user, index) => (
                                <tr key={`${user.email}-${index}`}>
                                    <td>{user.name}</td>
                                    <td>{user.email}</td>
                                    <td>{user.phoneNumber || user.mobile}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </Nav>
        </>
    );
}
